import {PointerOwnership} from './multiplayer.js';
// All pointers have independent ownership; camera gestures cannot place armies.
export function bind3DInput(canvas,runtime,{pick,down,move,up,cancel=()=>{},cameraMode=()=>false,ownerAt=()=>0}={}){const {B,scene,camera}=runtime,pointers=new Map(),ownership=new PointerOwnership(ownerAt);let pinch=null;
 function ground(e){const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*runtime.engine.getRenderWidth()/rect.width,y=(e.clientY-rect.top)*runtime.engine.getRenderHeight()/rect.height,ray=B.Ray.CreateNew(x,y,runtime.engine.getRenderWidth(),runtime.engine.getRenderHeight(),B.Matrix.Identity(),camera.getViewMatrix(),camera.getProjectionMatrix()),t=-ray.origin.y/ray.direction.y;if(!Number.isFinite(t)||t<0)return null;const p=ray.origin.add(ray.direction.scale(t));return{x:p.x,z:p.z};}
 function onDown(e){e.preventDefault();canvas.setPointerCapture(e.pointerId);const p={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,camera:cameraMode()||e.button===2,start:ground(e)};pointers.set(e.pointerId,p);if(p.camera){if(pointers.size===2)pinch=Math.hypot(...[...pointers.values()].reduce((a,p,i)=>i?[a[0]-p.x,a[1]-p.y]:[p.x,p.y],[]));return;}if(p.start){p.owner=ownership.begin(e.pointerId,p.start);p.handle=down?.(p.start,e,p.owner);}}
 function onMove(e){const p=pointers.get(e.pointerId);if(!p)return;e.preventDefault();if(p.camera){const dx=e.clientX-p.lastX,dy=e.clientY-p.lastY;if(pointers.size===2){const list=[...pointers.values()];p.x=e.clientX;p.y=e.clientY;const d=Math.hypot(list[0].x-list[1].x,list[0].y-list[1].y);if(pinch)camera.radius=Math.max(camera.lowerRadiusLimit,Math.min(camera.upperRadiusLimit,camera.radius*pinch/(d||1)));pinch=d;}else{camera.alpha-=dx*.006;camera.beta=Math.max(camera.lowerBetaLimit,Math.min(camera.upperBetaLimit,camera.beta+dy*.005));}}else{const at=ground(e);if(at)move?.(at,p.handle,e);}p.lastX=e.clientX;p.lastY=e.clientY;}
 function onUp(e){const p=pointers.get(e.pointerId);if(!p)return;e.preventDefault();if(!p.camera)up?.(ground(e),p.handle,e);pointers.delete(e.pointerId);ownership.end(e.pointerId);pinch=null;}
 function wheel(e){e.preventDefault();camera.radius=Math.max(camera.lowerRadiusLimit,Math.min(camera.upperRadiusLimit,camera.radius+e.deltaY*.015));}
 function stop(){pointers.clear();ownership.clear();pinch=null;cancel();}
 canvas.addEventListener('pointerdown',onDown);canvas.addEventListener('pointermove',onMove);canvas.addEventListener('pointerup',onUp);canvas.addEventListener('pointercancel',onUp);canvas.addEventListener('lostpointercapture',onUp);canvas.addEventListener('wheel',wheel,{passive:false});const context=e=>e.preventDefault();canvas.addEventListener('contextmenu',context);
 return{ground,cancel:stop,dispose(){stop();for(const [n,f]of [['pointerdown',onDown],['pointermove',onMove],['pointerup',onUp],['pointercancel',onUp],['lostpointercapture',onUp],['wheel',wheel],['contextmenu',context]])canvas.removeEventListener(n,f);}};
}
